/bin/bash -lc "nb cells 20260822_measure.ipynb 2,38; menv python -c 'from hera.analysis import *; import numpy as np
for i in [5,6,7]:
 r=open_run(f\"data/{i}\"); print(\"RUN\",i)
 for c in [\"sr0_X\",\"sr1_X\",\"k_2400_tg_curr\",\"k_2400_bg_curr\",\"T_sample\"]: print(c,np.percentile(r.col(c),[0,50,100]))
 if i>5:
  cs=resolve_channels(r.meta); ic=current_channel(cs); vc=next(c for c in cs if c.cid==\"sr1\"); R=abs((r.col(vc.col)/vc.gain)/(r.col(ic.col)/ic.gain)); B=r.col(\"magnet_field\"); print(\"R\",np.percentile(R,[0,50,100]));
  try: print(sdh_onset(R,B,r_full_scale=5000).summary())
  except Exception as e: print(type(e).__name__,e)
 else:
  t=r.col(\"time\").reshape(63,66); print(\"inrow sec\",np.percentile(np.diff(t,axis=1),[10,50,90]),\"turn sec\",np.percentile(t[1:,0]-t[:-1,-1],[10,50,90]))'"

